    {
      "name": "_get_incomplete_verification_files",
      "signature": "_get_incomplete_verification_files(layer_files: list[str], input_dir: str, output_dir: str, work_dir: str) -> list[str]",
      "pre_condition": "layer_files is a list of relative paths to extracted function files. input_dir is the extracted_functions/ root. output_dir is the verification output directory. work_dir is the fm_agent/ workspace.",
      "post_condition": "Returns the subset of layer_files for which both .spec.json and .info.json sidecar files exist and are valid, but no verification verdict output has been written."
    },
    {
      "name": "streaming_reasoner",
      "signature": "streaming_reasoner(input_dir: str, output_dir: str, file_list: list[str], proj_dir: str, work_dir: str, spec_procs: list | None, already_processed: set[str], resume: bool, bug_validator_path: str | None) -> set[str]",
      "pre_condition": "input_dir is the extracted_functions/ directory containing function files with complete spec/info sidecars. output_dir is the destination directory for verification verdict JSON files. file_list identifies the functions in scope. proj_dir is the project root. spec_procs is a list of concurrent.futures.Future objects for ongoing spec-generation tasks, or None.",
      "post_condition": "For each function in scope whose spec/info sidecars are complete, has not yet been processed, and is not in already_processed, runs block-level Hoare-style reasoning to verify the function body against its specification. Produces a verdict JSON file under output_dir. For each MISMATCH verdict, dispatches a bug validation agent that builds and executes a probe script, producing a bug_validation/<bug_id>.md report. Returns the set of function file paths newly processed."
    },
    {
      "name": "_run_spec_generation_batch",
      "signature": "_run_spec_generation_batch(proj_dir: str, work_dir: str, attempt: int, phase_num: int, layer_idx: int, batch_rel_dir: str, batch_info: dict) -> int",
      "pre_condition": "proj_dir is the project root directory. work_dir contains the workflow_spec_step4_batch.md instruction file. attempt is a positive integer tracking the current retry attempt. batch_info is a dict containing a 'file' key naming the batch prompt file, a 'functions' list of relative function paths, and a 'num_pending' count of unspecced functions.",
      "post_condition": "For each function listed in the batch, .spec.json and .info.json sidecar files are written next to the corresponding extracted source file according to the batch prompt instructions. Returns the subprocess exit code: 0 for success, non-zero for failure."
    },
    {
      "name": "is_file_ready",
      "signature": "is_file_ready(filepath: str) -> bool",
      "pre_condition": "filepath is an absolute path to an extracted function source file.",
      "post_condition": "Returns True when both a .spec.json and a .info.json sidecar file exist next to filepath and each contains valid JSON conforming to the metadata sidecar schema. Returns False otherwise."
    }
  ]
}
"}

